begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir fixtures/test-districts.psql
-- Synthetic users, districts and cases only, fully rolled back.
insert into auth.users(id,email,email_confirmed_at) select ('22222222-2222-4222-8222-'||lpad(n::text,12,'0'))::uuid,'workflow-'||n||'@example.test',now() from generate_series(1,8) n;
update public.profiles set role=case right(id::text,1) when '1' then 'coordinator'::public.user_role when '2' then 'field_officer'::public.user_role when '3' then 'viewer'::public.user_role when '4' then 'admin'::public.user_role when '6' then 'coordinator'::public.user_role when '7' then 'field_officer'::public.user_role else 'pending'::public.user_role end,status=case when right(id::text,1) in ('5','8') then 'pending'::public.account_status else 'active'::public.account_status end where id::text like '22222222-%';
insert into public.profile_district_grants(user_id,district_code,granted_by) select id,case when right(id::text,1)='6' then 'TEST-B' else 'TEST-A' end,'22222222-2222-4222-8222-000000000004' from public.profiles where id::text like '22222222-%';
insert into public.hotspot_observations(id,observation_key,source,satellite,instrument,latitude,longitude,detected_at,raw_payload,district_id,data_mode)
select 'dddddddd-dddd-4ddd-8ddd-000000000001','workflow-demo','DEMO_SIMULATION','SIMULATED','SIMULATED',1,1,now(),'{"provenance":"Synthetic workflow test"}',id,'demo' from public.districts where code='TEST-A';
insert into public.teams(id,name,district_id,authority_type) select 'eeeeeeee-eeee-4eee-8eee-000000000001','Synthetic test team',id,'Synthetic test authority' from public.districts where code='TEST-A';
insert into public.team_members(team_id,user_id,availability) values('eeeeeeee-eeee-4eee-8eee-000000000001','22222222-2222-4222-8222-000000000002','available');
set local role anon;
select throws_ok($$select public.create_incident('dddddddd-dddd-4ddd-8ddd-000000000001','Synthetic','Synthetic test reason')$$,'42501',null,'anon cannot create');
select throws_ok($$select public.mutate_incident(gen_random_uuid(),1,'verify','{}')$$,'42501',null,'anon cannot verify');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000005',true);
select throws_ok($$select public.create_incident('dddddddd-dddd-4ddd-8ddd-000000000001','Synthetic','Synthetic test reason')$$,'42501',null,'pending cannot create');
select is((select count(*)::int from public.staff_roster()),0,'pending cannot inspect roster');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000003',true);
select throws_ok($$select public.create_incident('dddddddd-dddd-4ddd-8ddd-000000000001','Synthetic','Synthetic test reason')$$,'42501',null,'viewer cannot create');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000001',true);
select lives_ok($$select public.create_incident('dddddddd-dddd-4ddd-8ddd-000000000001','Synthetic workflow case','Synthetic test opening reason')$$,'coordinator can create from scoped observation');
select set_config('test.incident',(select id::text from public.incidents where title='Synthetic workflow case'),true);
select is((select verification_status::text from public.incidents where id=current_setting('test.incident')::uuid),'needs_more_information','creation never confirms');
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,1,'verify','{"decision":"confirmed","reason":"short"}')$$,'22023',null,'verification reason required');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,1,'verify','{"decision":"confirmed","reason":"Synthetic human confirmation test"}')$$,'human confirms with reason');
select is((select row_version from public.incidents where id=current_setting('test.incident')::uuid),2::bigint,'atomic version increments');
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,1,'verify','{"decision":"not_confirmed","reason":"Synthetic stale request test"}')$$,'40001',null,'stale tab denied');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,2,'verify','{"decision":"not_confirmed","reason":"Synthetic correction test reason"}')$$,'decision can be corrected');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,3,'verify','{"decision":"needs_more_information","reason":"Synthetic uncertainty test reason"}')$$,'all three decisions accepted');
select is((select count(*)::int from public.verification_decisions where incident_id=current_setting('test.incident')::uuid),3,'all decisions retained');
select is((select count(*)::int from public.verification_decisions where incident_id=current_setting('test.incident')::uuid and supersedes_id is not null),2,'corrections reference prior decisions');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,4,'priority','{"priority":"high","reason":"Synthetic manual priority justification"}')$$,'authorized manual priority');
select is((select recommended_priority::text from public.incidents where id=current_setting('test.incident')::uuid),'unassessed','manual priority never activates unapproved algorithm');
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,5,'assign','{"owner_id":"22222222-2222-4222-8222-000000000007","team_id":"eeeeeeee-eeee-4eee-8eee-000000000001","reason":"Synthetic ineligible membership test"}')$$,'22023',null,'non-member officer denied');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,5,'assign','{"owner_id":"22222222-2222-4222-8222-000000000002","team_id":"eeeeeeee-eeee-4eee-8eee-000000000001","reason":"Synthetic valid team assignment test"}')$$,'eligible officer assigned');
select is((select count(*)::int from public.assignments where incident_id=current_setting('test.incident')::uuid and ended_at is null),1,'one active assignment');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000006',true);
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,6,'verify','{"decision":"confirmed","reason":"Synthetic out of area test reason"}')$$,'42501',null,'out-of-area coordinator denied');
select is((select count(*)::int from public.incident_events where incident_id=current_setting('test.incident')::uuid),0,'out-of-area history invisible');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000007',true);
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,6,'status','{"status":"in_progress","reason":"Synthetic unassigned officer test"}')$$,'42501',null,'unassigned field officer cannot progress');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000002',true);
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,6,'verify','{"decision":"confirmed","reason":"Synthetic field officer denial test"}')$$,'42501',null,'assigned officer cannot verify');
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,6,'priority','{"priority":"critical","reason":"Synthetic field officer denial test"}')$$,'42501',null,'assigned officer cannot override priority');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,6,'status','{"status":"in_progress","reason":"Synthetic field progress test reason"}')$$,'assigned officer can progress');
select lives_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,7,'report',jsonb_build_object('reason','Synthetic timestamped field report','observed_at',now()))$$,'assigned officer can report');
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,8,'status','{"status":"assigned","reason":"Synthetic invalid state transition"}')$$,'22023',null,'invalid state reversal denied');
select is((select count(*)::int from public.notifications where recipient_id='22222222-2222-4222-8222-000000000002'),1,'recipient sees assignment notification');
select is((select count(*)::int from public.notifications where recipient_id='22222222-2222-4222-8222-000000000001'),0,'other recipient notifications hidden');
select throws_ok($$update public.verification_decisions set reason='Synthetic overwrite'$$,'42501',null,'history has no direct update grants');
select throws_ok($$select public.begin_ingestion('TEST',now(),now())$$,'42501',null,'human cannot invoke private job');
reset role;
select throws_ok($$update public.incident_events set note='changed' where incident_id=current_setting('test.incident')::uuid$$,'42501',null,'history append-only even for operator');
set local role service_role;
select throws_ok($$select public.mutate_incident(current_setting('test.incident')::uuid,8,'verify','{}')$$,'42501',null,'automation cannot call verification RPC');
select lives_ok($$select public.begin_ingestion('SYNTHETIC_JOB',now(),now())$$,'private job can begin');
select throws_ok($$select public.begin_ingestion('SYNTHETIC_JOB',now(),now())$$,'55000',null,'overlap and frequent sync denied');
select lives_ok($$select public.finish_ingestion((select id from public.ingest_runs where source='SYNTHETIC_JOB'), '[]')$$,'empty successful response is recorded');
select is((select rows_seen from public.ingest_runs where source='SYNTHETIC_JOB'),0::bigint,'empty response is not fabricated points');
reset role;
-- Private Storage + metadata: same area grant matrix as incident reads.
insert into storage.objects(bucket_id,name,owner_id,metadata) values('incident-evidence','demo/'||current_setting('test.incident')||'/synthetic.pdf','22222222-2222-4222-8222-000000000001','{"mimetype":"application/pdf","size":100}');
insert into public.evidence_files(incident_id,uploaded_by,storage_path,mime_type,size_bytes,description,captured_at) values(current_setting('test.incident')::uuid,'22222222-2222-4222-8222-000000000001','demo/'||current_setting('test.incident')||'/synthetic.pdf','application/pdf',100,'Synthetic evidence security test only',now());
set local role anon;
select is((select count(*)::int from storage.objects where name='demo/'||current_setting('test.incident')||'/synthetic.pdf'),0,'anon cannot read private evidence');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000005',true);
select is((select count(*)::int from public.evidence_files where incident_id=current_setting('test.incident')::uuid),0,'pending evidence metadata denied');
select is((select count(*)::int from storage.objects where name='demo/'||current_setting('test.incident')||'/synthetic.pdf'),0,'pending storage read denied');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000006',true);
select is((select count(*)::int from storage.objects where name='demo/'||current_setting('test.incident')||'/synthetic.pdf'),0,'out-of-area storage denied');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000003',true);
select is((select count(*)::int from storage.objects where name='demo/'||current_setting('test.incident')||'/synthetic.pdf'),1,'scoped viewer may read registered private evidence');
select throws_ok($$insert into storage.objects(bucket_id,name) values('incident-evidence','demo/'||current_setting('test.incident')||'/denied.pdf')$$,'42501',null,'viewer cannot upload');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000002',true);
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id) values('incident-evidence','demo/'||current_setting('test.incident')||'/officer.pdf','22222222-2222-4222-8222-000000000002')$$,'assigned officer can upload to own incident');
select is((select count(*)::int from storage.objects where name='demo/'||current_setting('test.incident')||'/synthetic.pdf'),1,'assigned officer reads evidence');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000004',true);
select is((select count(*)::int from storage.objects where name='demo/'||current_setting('test.incident')||'/synthetic.pdf'),1,'scoped admin reads evidence');
reset role;
-- Sensor corrections retain a single live row; synthetic simulated live records roll back.
set local role service_role;
select public.begin_ingestion('SYNTHETIC_CORRECTION',now(),now());
select public.finish_ingestion((select id from public.ingest_runs where source='SYNTHETIC_CORRECTION'),jsonb_build_array(jsonb_build_object('observation_key','synthetic-correction','satellite','SIMULATED','instrument','SIMULATED','latitude',10,'longitude',10,'detected_at',now(),'confidence_raw','n','confidence_kind','VIIRS categorical l/n/h','raw_payload','{"fixture":true}'::jsonb)));
reset role;
update public.ingest_runs set started_at=now()-interval '6 minutes' where source='SYNTHETIC_CORRECTION';
set local role service_role;
select public.begin_ingestion('SYNTHETIC_CORRECTION',now(),now());
select public.finish_ingestion((select id from public.ingest_runs where source='SYNTHETIC_CORRECTION' and status='running'),jsonb_build_array(jsonb_build_object('observation_key','synthetic-correction','satellite','SIMULATED','instrument','SIMULATED','latitude',10,'longitude',10,'detected_at',now(),'confidence_raw','h','confidence_kind','VIIRS categorical l/n/h','raw_payload','{"fixture":true,"revision":2}'::jsonb)));
select is((select count(*)::int from public.hotspot_observations where observation_key='synthetic-correction'),1,'rerun/upstream correction never duplicates observations');
select is((select confidence_raw from public.hotspot_observations where observation_key='synthetic-correction'),'h','source correction updates raw confidence');
reset role;
select * from finish();
rollback;
